1	const { Request, Response, NextFunction } = require('express')
2	const Path = require('path')
3	const fs = require('../libs/fsExtra')
4	const cron = require('../libs/nodeCron')
5	const uaParserJs = require('../libs/uaParser')
6	const Logger = require('../Logger')
7	const SocketAuthority = require('../SocketAuthority')
8	const Database = require('../Database')
9	
10	const zipHelpers = require('../utils/zipHelpers')
11	const { reqSupportsWebp, clampPositiveInt } = require('../utils/index')
12	const { ScanResult, AudioMimeType } = require('../utils/constants')
13	const { getAudioMimeTypeFromExtname, encodeUriPath } = require('../utils/fileUtils')
14	const LibraryItemScanner = require('../scanner/LibraryItemScanner')
15	const AudioFileScanner = require('../scanner/AudioFileScanner')
16	const Scanner = require('../scanner/Scanner')
17	
18	const RssFeedManager = require('../managers/RssFeedManager')
19	const CacheManager = require('../managers/CacheManager')
20	const CoverManager = require('../managers/CoverManager')
21	const ShareManager = require('../managers/ShareManager')
22	
23	/**
24	 * @typedef RequestUserObject
25	 * @property {import('../models/User')} user
26	 *
27	 * @typedef {Request & RequestUserObject} RequestWithUser
28	 *
29	 * @typedef RequestEntityObject
30	 * @property {import('../models/LibraryItem')} libraryItem
31	 *
32	 * @typedef {RequestWithUser & RequestEntityObject} LibraryItemControllerRequest
33	 *
34	 * @typedef RequestLibraryFileObject
35	 * @property {import('../objects/files/LibraryFile')} libraryFile
36	 *
37	 * @typedef {RequestWithUser & RequestEntityObject & RequestLibraryFileObject} LibraryItemControllerRequestWithFile
38	 */
39	
40	/**
41	 * Enforce per-item access for batch item routes
42	 *
43	 * @param {RequestWithUser} req
44	 * @param {Response} res
45	 * @param {import('../models/LibraryItem')[]} libraryItems
46	 * @returns {boolean} true if the user may access every item; false if 403 was sent
47	 */
48	function ensureUserCanAccessLibraryItemsForBatch(req, res, libraryItems) {
49	  for (const libraryItem of libraryItems) {
50	    if (!req.user.checkCanAccessLibraryItem(libraryItem)) {
51	      res.sendStatus(403)
52	      return false
53	    }
54	  }
55	  return true
56	}
57	
58	class LibraryItemController {
59	  constructor() {}
60	
61	  /**
62	   * GET: /api/items/:id
63	   * Optional query params:
64	   * ?include=progress,rssfeed,downloads,share
65	   * ?expanded=1
66	   *
67	   * @param {LibraryItemControllerRequest} req
68	   * @param {Response} res
69	   */
70	  async findOne(req, res) {
71	    const includeEntities = (req.query.include || '').split(',')
72	    if (req.query.expanded == 1) {
73	      const item = req.libraryItem.toOldJSONExpanded()
74	
75	      // Include users media progress
76	      if (includeEntities.includes('progress')) {
77	        const episodeId = req.query.episode || null
78	        item.userMediaProgress = req.user.getOldMediaProgress(item.id, episodeId)
79	      }
80	
81	      if (includeEntities.includes('rssfeed')) {
82	        const feedData = await RssFeedManager.findFeedForEntityId(item.id)
83	        item.rssFeed = feedData?.toOldJSONMinified() || null
84	      }
85	
86	      if (item.mediaType === 'book' && req.user.isAdminOrUp && includeEntities.includes('share')) {
87	        item.mediaItemShare = ShareManager.findByMediaItemId(item.media.id)
88	      }
89	
90	      if (item.mediaType === 'podcast' && includeEntities.includes('downloads')) {
91	        const downloadsInQueue = this.podcastManager.getEpisodeDownloadsInQueue(req.libraryItem.id)
92	        item.episodeDownloadsQueued = downloadsInQueue.map((d) => d.toJSONForClient())
93	        if (this.podcastManager.currentDownload?.libraryItemId === req.libraryItem.id) {
94	          item.episodesDownloading = [this.podcastManager.currentDownload.toJSONForClient()]
95	        }
96	      }
97	
98	      return res.json(item)
99	    }
100	    res.json(req.libraryItem.toOldJSON())
101	  }
102	
103	  /**
104	   * DELETE: /api/items/:id
105	   * Delete library item. Will delete from database and file system if hard delete is requested.
106	   * Optional query params:
107	   * ?hard=1
108	   *
109	   * @this {import('../routers/ApiRouter')}
110	   *
111	   * @param {LibraryItemControllerRequest} req
112	   * @param {Response} res
113	   */
114	  async delete(req, res) {
115	    const hardDelete = req.query.hard == 1 // Delete from file system
116	    const libraryItemPath = req.libraryItem.path
117	
118	    const mediaItemIds = []
119	    const authorIds = []
120	    const seriesIds = []
121	    if (req.libraryItem.isPodcast) {
122	      mediaItemIds.push(...req.libraryItem.media.podcastEpisodes.map((ep) => ep.id))
123	    } else {
124	      mediaItemIds.push(req.libraryItem.media.id)
125	      if (req.libraryItem.media.authors?.length) {
126	        authorIds.push(...req.libraryItem.media.authors.map((au) => au.id))
127	      }
128	      if (req.libraryItem.media.series?.length) {
129	        seriesIds.push(...req.libraryItem.media.series.map((se) => se.id))
130	      }
131	    }
132	
133	    await this.handleDeleteLibraryItem(req.libraryItem.id, mediaItemIds, req.libraryItem.libraryId)
134	    if (hardDelete) {
135	      Logger.info(`[LibraryItemController] Deleting library item from file system at "${libraryItemPath}"`)
136	      await fs.remove(libraryItemPath).catch((error) => {
137	        Logger.error(`[LibraryItemController] Failed to delete library item from file system at "${libraryItemPath}"`, error)
138	      })
139	    }
140	
141	    if (authorIds.length) {
142	      await this.checkRemoveAuthorsWithNoBooks(authorIds)
143	    }
144	    if (seriesIds.length) {
145	      await this.checkRemoveEmptySeries(seriesIds)
146	    }
147	
148	    await Database.resetLibraryIssuesFilterData(req.libraryItem.libraryId)
149	    res.sendStatus(200)
150	  }
151	
152	  static handleDownloadError(error, res) {
153	    if (!res.headersSent) {
154	      if (error.code === 'ENOENT') {
155	        return res.status(404).send('File not found')
156	      } else {
157	        return res.status(500).send('Download failed')
158	      }
159	    }
160	  }
161	
162	  /**
163	   * GET: /api/items/:id/download
164	   * Download library item. Zip file if multiple files.
165	   *
166	   * @param {LibraryItemControllerRequest} req
167	   * @param {Response} res
168	   */
169	  async download(req, res) {
170	    if (!req.user.canDownload) {
171	      Logger.warn(`User "${req.user.username}" attempted to download without permission`)
172	      return res.sendStatus(403)
173	    }
174	    const libraryItemPath = req.libraryItem.path
175	    const itemTitle = req.libraryItem.media.title
176	
177	    Logger.info(`[LibraryItemController] User "${req.user.username}" requested download for item "${itemTitle}" at "${libraryItemPath}"`)
178	
179	    try {
180	      // If library item is a single file in root dir then no need to zip
181	      if (req.libraryItem.isFile) {
182	        // Express does not set the correct mimetype for m4b files so use our defined mimetypes if available
183	        const audioMimeType = getAudioMimeTypeFromExtname(Path.extname(libraryItemPath))
184	        if (audioMimeType) {
185	          res.setHeader('Content-Type', audioMimeType)
186	        }
187	        await new Promise((resolve, reject) => res.download(libraryItemPath, req.libraryItem.relPath, (error) => (error ? reject(error) : resolve())))
188	      } else {
189	        const filename = `${itemTitle}.zip`
190	        await zipHelpers.zipDirectoryPipe(libraryItemPath, filename, res)
191	      }
192	      Logger.info(`[LibraryItemController] Downloaded item "${itemTitle}" at "${libraryItemPath}"`)
193	    } catch (error) {
194	      Logger.error(`[LibraryItemController] Download failed for item "${itemTitle}" at "${libraryItemPath}"`, error)
195	      LibraryItemController.handleDownloadError(error, res)
196	    }
197	  }
198	
199	  /**
200	   * PATCH: /items/:id/media
201	   * Update media for a library item. Will create new authors & series when necessary
202	   *
203	   * @this {import('../routers/ApiRouter')}
204	   *
205	   * @param {LibraryItemControllerRequest} req
206	   * @param {Response} res
207	   */
208	  async updateMedia(req, res) {
209	    const mediaPayload = req.body
210	
211	    if (mediaPayload.url) {
212	      await LibraryItemController.prototype.uploadCover.bind(this)(req, res, false)
213	      if (res.writableEnded || res.headersSent) return
214	    }
215	
216	    // Podcast specific
217	    let isPodcastAutoDownloadUpdated = false
218	    if (req.libraryItem.isPodcast) {
219	      if (mediaPayload.autoDownloadEpisodes !== undefined && req.libraryItem.media.autoDownloadEpisodes !== mediaPayload.autoDownloadEpisodes) {
220	        isPodcastAutoDownloadUpdated = true
221	      } else if (mediaPayload.autoDownloadSchedule !== undefined && req.libraryItem.media.autoDownloadSchedule !== mediaPayload.autoDownloadSchedule) {
222	        isPodcastAutoDownloadUpdated = true
223	      }
224	
225	      if (mediaPayload.autoDownloadSchedule && !cron.validate(mediaPayload.autoDownloadSchedule)) {
226	        Logger.error(`[LibraryItemController] Invalid auto download schedule cron expression "${mediaPayload.autoDownloadSchedule}" for library item "${req.libraryItem.media.title}"`)
227	        return res.status(400).send('Invalid auto download schedule cron expression')
228	      }
229	    }
230	
231	    let hasUpdates = (await req.libraryItem.media.updateFromRequest(mediaPayload)) || mediaPayload.url
232	
233	    if (req.libraryItem.isBook && Array.isArray(mediaPayload.metadata?.series)) {
234	      const seriesUpdateData = await req.libraryItem.media.updateSeriesFromRequest(mediaPayload.metadata.series, req.libraryItem.libraryId)
235	      if (seriesUpdateData?.seriesRemoved.length) {
236	        // Check remove empty series
237	        Logger.debug(`[LibraryItemController] Series were removed from book. Check if series are now empty.`)
238	        await this.checkRemoveEmptySeries(seriesUpdateData.seriesRemoved.map((se) => se.id))
239	      }
240	      if (seriesUpdateData?.seriesAdded.length) {
241	        // Add series to filter data
242	        seriesUpdateData.seriesAdded.forEach((se) => {
243	          Database.addSeriesToFilterData(req.libraryItem.libraryId, se.name, se.id)
244	        })
245	      }
246	      if (seriesUpdateData?.hasUpdates) {
247	        hasUpdates = true
248	      }
249	    }
250	
251	    if (req.libraryItem.isBook && Array.isArray(mediaPayload.metadata?.authors)) {
252	      const authorNames = mediaPayload.metadata.authors.map((au) => (typeof au.name === 'string' ? au.name.trim() : null)).filter((au) => au)
253	      const authorUpdateData = await req.libraryItem.media.updateAuthorsFromRequest(authorNames, req.libraryItem.libraryId)
254	      if (authorUpdateData?.authorsRemoved.length) {
255	        // Check remove empty authors
256	        Logger.debug(`[LibraryItemController] Authors were removed from book. Check if authors are now empty.`)
257	        await this.checkRemoveAuthorsWithNoBooks(authorUpdateData.authorsRemoved.map((au) => au.id))
258	        hasUpdates = true
259	      }
260	      if (authorUpdateData?.authorsAdded.length) {
261	        // Add authors to filter data
262	        authorUpdateData.authorsAdded.forEach((au) => {
263	          Database.addAuthorToFilterData(req.libraryItem.libraryId, au.name, au.id)
264	        })
265	        hasUpdates = true
266	      }
267	    }
268	
269	    if (hasUpdates) {
270	      req.libraryItem.changed('updatedAt', true)
271	      await req.libraryItem.save()
272	
273	      await req.libraryItem.saveMetadataFile()
274	
275	      if (isPodcastAutoDownloadUpdated) {
276	        this.cronManager.checkUpdatePodcastCron(req.libraryItem)
277	      }
278	
279	      Logger.debug(`[LibraryItemController] Updated library item media ${req.libraryItem.media.title}`)
280	      SocketAuthority.libraryItemEmitter('item_updated', req.libraryItem)
281	    }
282	    res.json({
283	      updated: hasUpdates,
284	      libraryItem: req.libraryItem.toOldJSON()
285	    })
286	  }
287	
288	  /**
289	   * POST: /api/items/:id/cover
290	   *
291	   * @param {LibraryItemControllerRequest} req
292	   * @param {Response} res
293	   * @param {boolean} [updateAndReturnJson=true] - Allows the function to be used for both direct API calls and internally
294	   */
295	  async uploadCover(req, res, updateAndReturnJson = true) {
296	    if (!req.user.canUpload) {
297	      Logger.warn(`User "${req.user.username}" attempted to upload a cover without permission`)
298	      return res.sendStatus(403)
299	    }
300	
301	    let result = null
302	    if (req.body?.url) {
303	      Logger.debug(`[LibraryItemController] Requesting download cover from url "${req.body.url}"`)
304	      result = await CoverManager.downloadCoverFromUrlNew(req.body.url, req.libraryItem.id, req.libraryItem.isFile ? null : req.libraryItem.path)
305	    } else if (req.files?.cover) {
306	      Logger.debug(`[LibraryItemController] Handling uploaded cover`)
307	      result = await CoverManager.uploadCover(req.libraryItem, req.files.cover)
308	    } else {
309	      return res.status(400).send('Invalid request no file or url')
310	    }
311	
312	    if (result?.error) {
313	      return res.status(400).send(result.error)
314	    } else if (!result?.cover) {
315	      return res.status(500).send('Unknown error occurred')
